#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

at::Tensor windowed_causal_attention_custom_impl_npu(const at::Tensor& q_bhnd,
                                                     const at::Tensor& k_bhnd,
                                                     const at::Tensor& v_bhnd,
                                                     int64_t window_size) {
    TORCH_CHECK(q_bhnd.device().type() == at::kPrivateUse1, "q must be on NPU");
    TORCH_CHECK(k_bhnd.device().type() == at::kPrivateUse1, "k must be on NPU");
    TORCH_CHECK(v_bhnd.device().type() == at::kPrivateUse1, "v must be on NPU");
    TORCH_CHECK(q_bhnd.sizes() == k_bhnd.sizes() && q_bhnd.sizes() == v_bhnd.sizes(), "q,k,v shape mismatch");

    at::Tensor out = at::empty_like(q_bhnd);

    // prepare window size tensor on NPU
    auto opts_i32 = at::TensorOptions().dtype(at::kInt).device(q_bhnd.device());
    at::Tensor w = at::empty({1}, opts_i32);
    w.fill_(static_cast<int>(window_size));

    EXEC_NPU_CMD(aclnnWindowedCausalAttentionCustom, q_bhnd, k_bhnd, v_bhnd, w, out);
    return out;
}

